                @for (g of grades; track g) {
                  <option [value]="g" [selected]="p.grade === g">{{ g }}</option>
                }
              </select>
            </td>
            <td>
              <label class="visually-hidden" [for]="'person-patron-edit-' + p.id">
                Patrons for {{ p.name }}
